    private static File dir;
    private static String caPem;
    private static X509Certificate caCert;
    private static X509Certificate leaf;
    private static PrivateKey leafKey;
    /** ca's subject and key, signed by an expired CA, itself expired (an old cross-sign of the valid given CA). */
    private static X509Certificate expiredCrossOfCa;
    /** ca's subject and key, self-issued, expired (the CA certificate before it was renewed with the same key). */
    private static X509Certificate oldSameKeyCa;
    private static SSLSocketFactory jdkFactoryTrustingCa;

    private final InMemoryHttpAdapter adapter = new InMemoryHttpAdapter();
    private final TestApp t = TestApp.create(adapter);
    private final RestApp app = t.app();
    private final List<Closeable> closeables = new ArrayList<>();
    private final List<Throwable> errors = Collections.synchronizedList(new ArrayList<Throwable>());
    private boolean started;

    @BeforeClass
    public static void make() throws Exception {
        dir = java.nio.file.Files.createTempDirectory("lp-trust-r3").toFile();
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "ca", "-keyalg", "RSA", "-keysize", "2048", "-dname",
                "CN=LP R3 CA", "-ext", "bc:c", "-validity", "3", "-keystore", "ca.p12");
        TestCertificates.keytool(dir, "-exportcert", "-rfc", "-alias", "ca", "-keystore", "ca.p12", "-file",
                "ca.pem");
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "old", "-keyalg", "RSA", "-keysize", "2048", "-dname",
                "CN=LP R3 Old Root", "-ext", "bc:c", "-validity", "2", "-startdate", "2000/01/01", "-keystore",
                "old.p12");
        // leaf for localhost issued by ca
        TestCertificates.keytool(dir, "-genkeypair", "-alias", "server", "-keyalg", "RSA", "-keysize", "2048",
                "-dname", "CN=localhost", "-validity", "3", "-keystore", "leaf.p12");
        TestCertificates.keytool(dir, "-certreq", "-alias", "server", "-keystore", "leaf.p12", "-file", "leaf.csr");
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "ca", "-keystore", "ca.p12", "-infile",
                "leaf.csr", "-outfile", "leaf.pem", "-ext", "SAN=dns:localhost,ip:127.0.0.1", "-validity", "3");
        // ca's own request, signed by the expired old root (expired cross-sign) and by ca itself (expired old copy)
        TestCertificates.keytool(dir, "-certreq", "-alias", "ca", "-keystore", "ca.p12", "-file", "ca.csr");
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "old", "-keystore", "old.p12", "-infile",
                "ca.csr", "-outfile", "cross.pem", "-ext", "bc:c", "-startdate", "2000/01/01", "-validity", "2");
        TestCertificates.keytool(dir, "-gencert", "-rfc", "-alias", "ca", "-keystore", "ca.p12", "-infile",
                "ca.csr", "-outfile", "oldca.pem", "-ext", "bc:c", "-startdate", "2000/01/01", "-validity", "2");

