        leaf = TestCertificates.parse(TestCertificates.read(new File(dir, "leaf.pem")));
        expiredCrossOfCa = TestCertificates.parse(TestCertificates.read(new File(dir, "cross.pem")));
        oldSameKeyCa = TestCertificates.parse(TestCertificates.read(new File(dir, "oldca.pem")));
        leafKey = (PrivateKey) TestCertificates.load(new File(dir, "leaf.p12"))
                .getKey("server", TestCertificates.PASSWORD.toCharArray());
        // fixture sanity
        leaf.verify(caCert.getPublicKey());
        assertEquals(caCert.getSubjectX500Principal(), expiredCrossOfCa.getSubjectX500Principal());
        assertEquals(caCert.getPublicKey(), expiredCrossOfCa.getPublicKey());
        assertEquals(caCert.getSubjectX500Principal(), oldSameKeyCa.getSubjectX500Principal());
        assertEquals(caCert.getPublicKey(), oldSameKeyCa.getPublicKey());
        oldSameKeyCa.verify(caCert.getPublicKey());

