    }

    private void assertReached(ClientResponse r, TlsBackend b) {
        StringBuilder causes = new StringBuilder();
        synchronized (errors) {
            for (Throwable e : errors) {
                for (Throwable c = e; c != null; c = c.getCause()) {
                    causes.append(" <- ").append(c);
                }
            }
        }
        assertEquals("status (errors:" + causes + ")", 200, r.status());
        assertEquals("ok", r.text());
        assertTrue(b.requestHead(), b.requestHead().startsWith("GET /api/x HTTP/1.1\r\n"));
    }

    // control: the JDK's own trust over the same single CA accepts [leaf, ca, expired cross-sign of ca]
    // FR-PROXY-022 AC-2
    @Test(timeout = 30000)
    public void control_jdkTrustReachesChainWithExpiredCrossSignAfterTheGivenCa() throws Exception {
        TlsBackend b = backend(presenting(leaf, caCert, expiredCrossOfCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port()).sslSocketFactory(jdkFactoryTrustingCa)),
                b);
    }

    // FR-PROXY-022 AC-2: with .trustCertificates(caPem), a backend whose certificate that CA issued for the target
    // host is reached; the backend also sends, after the valid given CA certificate, an old expired cross-sign of
    // that CA (a common leftover after a root rollover). The validated chain [leaf, ca] is entirely valid; the extra
    // certificate is not on it. The JDK trust over the same CA accepts (control above); trustCertificates must too.
    @Test(timeout = 30000)
    public void fr_PROXY_022_AC2_anExpiredCrossSignBeyondThePresentedGivenCaDoesNotRejectAValidChain()
            throws Exception {
        TlsBackend b = backend(presenting(leaf, caCert, expiredCrossOfCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port()).trustCertificates(caPem)), b);
    }

    // control: the JDK's own trust over the renewed CA accepts [leaf, the expired pre-renewal copy of that CA]
    // FR-PROXY-022 AC-2
    @Test(timeout = 30000)
    public void control_jdkTrustReachesChainPresentingTheExpiredPreRenewalCa() throws Exception {
        TlsBackend b = backend(presenting(leaf, oldSameKeyCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port()).sslSocketFactory(jdkFactoryTrustingCa)),
                b);
    }

    // FR-PROXY-022 AC-2: the CA was renewed with the same name and key and the user gives the renewed (valid)
    // certificate; the backend still sends the expired pre-renewal copy after its leaf. The leaf was issued by that
    // CA (same key) for the target host and is valid, and the given CA is valid, so the backend must be reached.
    @Test(timeout = 30000)
    public void fr_PROXY_022_AC2_anExpiredPreRenewalCopyOfTheGivenCaSentByTheBackendDoesNotRejectAValidChain()
            throws Exception {
        TlsBackend b = backend(presenting(leaf, oldSameKeyCa));
        assertReached(mountAndGet(Proxy.to("https://localhost:" + b.port()).trustCertificates(caPem)), b);
    }

    // FR-PROXY-022 AC-2 (visit-once probe): one presented node reachable through two presented parents (the given CA
    // presented twice and its expired cross) must not be rejected by the search when the leaf reaches the valid CA.
    @Test(timeout = 30000)
    public void fr_PROXY_022_AC2_duplicateGivenCaInChainIsReached() throws Exception {
